CREATE TABLE "CreditoVenta" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "ventaId" INTEGER NOT NULL, "planCreditoId" INTEGER NOT NULL, "principal" REAL NOT NULL, "interesTotal" REAL NOT NULL, "totalFinanciado" REAL NOT NULL, "saldoPendiente" REAL NOT NULL, "estado" TEXT NOT NULL DEFAULT 'ACTIVO', "planSnapshot" TEXT NOT NULL, "creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CreditoVenta_ventaId_fkey" FOREIGN KEY ("ventaId") REFERENCES "Venta"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "CreditoVenta_planCreditoId_fkey" FOREIGN KEY ("planCreditoId") REFERENCES "PlanCredito"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CreditoVenta_ventaId_key" ON "CreditoVenta"("ventaId");
CREATE TABLE "CuotaCredito" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "creditoVentaId" INTEGER NOT NULL, "numero" INTEGER NOT NULL, "venceEn" DATETIME NOT NULL, "capital" REAL NOT NULL, "interes" REAL NOT NULL, "monto" REAL NOT NULL, "saldo" REAL NOT NULL, "pagado" REAL NOT NULL DEFAULT 0, "estado" TEXT NOT NULL DEFAULT 'PENDIENTE', CONSTRAINT "CuotaCredito_creditoVentaId_fkey" FOREIGN KEY ("creditoVentaId") REFERENCES "CreditoVenta"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CuotaCredito_creditoVentaId_numero_key" ON "CuotaCredito"("creditoVentaId", "numero");
CREATE INDEX "CuotaCredito_estado_venceEn_idx" ON "CuotaCredito"("estado", "venceEn");
